.hover\:cms-primary-text:hover { color: var(--mwakwa-primary); }
.cms-cta-gradient { background: linear-gradient(90deg, var(--mwakwa-primary), var(--mwakwa-secondary)); }

/* ✅ Montserrat will be provided from next/font in layout.tsx */
:root {
  --background: #ffffff;
  --foreground: #171717;

  /* ✅ Replace geist with montserrat */
