"use client";

import { useEffect, useMemo, useState } from "react";
import { useParams } from "next/navigation";
import Header from "@/components/header/Header";
import Footer from "@/components/footer/Footer";
import { mwakwaData } from "@/lib/mwakwaBackend";

type Row = { body?: string; legal_name?: string; address_line1?: string; address_line2?: string; city?: string; region?: string; postal_code?: string; country?: string; support_email?: string; email?: string; phone?: string; registration_number?: string; };
function renderBody(body = "") { return body.split("\n").map((line,i)=> line.startsWith("# ") ? <h1 key={i} className="text-3xl md:text-4xl font-bold mt-2 mb-6">{line.slice(2)}</h1> : line.startsWith("## ") ? <h2 key={i} className="text-xl font-semibold mt-8 mb-3">{line.slice(3)}</h2> : !line.trim() ? <div key={i} className="h-2"/> : <p key={i} className="text-gray-700 leading-7 mb-3">{line}</p>); }
export default function LegalPage(){
 const params=useParams(); const slug=String(params?.slug||""); const [page,setPage]=useState<Row|null>(null); const [business,setBusiness]=useState<Row|null>(null); const [loaded,setLoaded]=useState(false);
 useEffect(()=>{ if(!slug)return; Promise.all([mwakwaData.contentPages.filter({slug,is_published:true},undefined,1,0),mwakwaData.businessInfo.filter({is_active:true},undefined,1,0)]).then(([p,b])=>{setPage(p?.[0]||null);setBusiness(b?.[0]||null)}).finally(()=>setLoaded(true));},[slug]);
 const address=useMemo(()=>business?[business.address_line1,business.address_line2,business.city,business.region,business.postal_code,business.country].filter(Boolean).map(String).join(", "):"",[business]);
 return <><Header/><main className="min-h-screen bg-gray-50 py-8 md:py-12"><article className="max-w-3xl mx-auto bg-white px-5 py-8 md:px-10 md:py-10 md:rounded-2xl md:shadow-sm">{!loaded?<p>Loading…</p>:page?renderBody(String(page.body||"")):<><h1 className="text-3xl font-bold">Page not found</h1><p className="mt-3 text-gray-600">This legal page is not currently published.</p></>} {page&&<section className="mt-10 border-t pt-6"><h2 className="text-xl font-semibold mb-3">Mwakwa operator</h2>{business?<div className="text-gray-700 space-y-1"><p>{String(business.legal_name||"")}</p>{address&&<p>{address}</p>}{(business.support_email||business.email)&&<p>Contact: {String(business.support_email||business.email||"")}</p>}{business.phone&&<p>Phone: {String(business.phone||"")}</p>}{business.registration_number&&<p>Registration: {String(business.registration_number||"")}</p>}</div>:<p className="text-gray-500">Operator details are being updated.</p>}</section>}</article></main><Footer/></>;
}

src/components/auth/AuthModal.tsx:
"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { mwakwaAuth } from "@/lib/mwakwaBackend";
import { Eye, EyeOff, X, Mail, Lock, User, Phone } from "lucide-react";

interface AuthModalProps {
  type: "signin" | "signup";
  isOpen: boolean;
  onClose: () => void;
  onSuccess: (userEmail: string) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({
  type,
  isOpen,
  onClose,
  onSuccess,
}) => {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      if (type === "signup") {
        if (password !== confirmPassword) {
          throw new Error("Passwords do not match");
        }
        if (password.length < 6) {
          throw new Error("Password must be at least 6 characters");
        }

        const result = await mwakwaAuth.register(email, password);
        const currentUser = await mwakwaAuth.me();
        if (currentUser) {
          await mwakwaAuth.updateMe({
            display_name: name,
            phone,
            account_type: "attendee",
            is_active: true,
          });
        }

        onSuccess(currentUser?.email || email);
        onClose();
        router.push("/");
      } else {
        await mwakwaAuth.login(email, password);
        const currentUser = await mwakwaAuth.me();
        onSuccess(currentUser?.email || email);
        onClose();
        router.push("/");
      }
    } catch (err) {
      const e = err as Error;
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSocialAuth = async (provider: "google") => {
    try {
      setLoading(true);
      setError("");

      if (provider === "google") {
        await mwakwaAuth.loginWithGoogle(`${window.location.origin}/profile`);
      }
    } catch (err) {
      const e = err as Error;
      setError(e.message);
      setLoading(false);
    }
  };

  const resetForm = () => {
    setEmail("");
    setPassword("");
    setConfirmPassword("");
    setName("");
    setPhone("");
    setError("");
    setShowPassword(false);
    setShowConfirmPassword(false);
  };

  const handleClose = () => {
    if (!loading) {
      resetForm();
      onClose();
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 p-4"
          onClick={handleClose}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            transition={{ duration: 0.2 }}
            className="bg-white rounded-2xl shadow-2xl w-full max-w-md relative overflow-hidden max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="bg-gradient-to-r from-blue-600 to-blue-700 px-6 py-8 relative">
              <button
                onClick={handleClose}
                disabled={loading}
                className="absolute top-4 right-4 text-white/80 hover:text-white transition-colors p-1 disabled:opacity-50"
              >
                <X className="w-5 h-5" />
              </button>
              <div className="text-center">
                <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-4">
                  <User className="w-8 h-8 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-white">
                  {type === "signin" ? "Log in" : "Sign up"}
                </h2>
                <p className="text-blue-100 mt-2 text-sm">
                  {type === "signin"
                    ? "Welcome back! Let's get you to your next event."
                    : "Tell us a little about you"}
                </p>
              </div>
            </div>

            {/* Social Auth */}
            <div className="p-6 pb-0">
              <div className="flex items-center justify-center">
                <button
                  type="button"
                  onClick={() => handleSocialAuth("google")}
                  disabled={loading}
                  className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg bg-white text-base text-gray-500 hover:bg-gray-50 font-semibold transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loading ? (
                    <>
                      <svg className="animate-spin h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Connecting...
                    </>
                  ) : (
                    <>
                      <svg className="w-5 h-5 mr-2" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path fill="#4285F4" d="M24 9.5c3.34 0 5.86 1.13 7.82 2.92l6.53-6.53C35.86 2.37 30.14 0 24 0 14.86 0 6.91 5.09 3.01 12.33l7.07 5.46C12.89 12.39 18.06 9.5 24 9.5z" />
                        <path fill="#34A853" d="M44 24.5c0-1.57-.14-3.07-.4-4.52H24v8.58h11.23c-1.22 4.41-5.11 7.4-9.82 7.4-5.94 0-10.9-4.04-12.72-9.6H1.2c4.08 7.91 12.01 13.52 22.8 13.52 7.15 0 13.41-2.39 17.8-6.54l-6.53-5.06z" />
                        <path fill="#FBBC04" d="M11.28 29.43c-1.88-.51-3.6-1.29-5.04-2.29l-7.07 5.46c2.81 4.54 6.89 7.7 11.58 9.38 2.24.8 4.67 1.22 7.21 1.22 2.54 0 4.97-.42 7.21-1.22l-7.07-5.46z" />
                        <path fill="#EA4335" d="M24 9.5c3.34 0 5.86 1.13 7.82 2.92l6.53-6.53C35.86 2.37 30.14 0 24 0 14.86 0 6.91 5.09 3.01 12.33l7.07 5.46C12.89 12.39 18.06 9.5 24 9.5z" />
                      </svg>
                      Sign in with Google
                    </>
                  )}
                </button>
              </div>
              <div className="relative flex justify-center py-4">
                <span className="px-2 bg-white text-gray-500 text-sm">or</span>
              </div>
            </div>

            {/* Form */}
            <div className="p-6 pt-0">
              <form onSubmit={handleSubmit} className="space-y-4">
                {type === "signup" && (
                  <>
                    <div className="relative">
                      <User className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                      <input
                        type="text"
                        placeholder="Your Name"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        required
                        disabled={loading}
                        className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 focus:bg-white disabled:opacity-50"
                      />
                    </div>
                    <div className="relative">
                      <Phone className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                      <input
                        type="tel"
                        placeholder="Phone Number"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        required
                        disabled={loading}
                        className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 focus:bg-white disabled:opacity-50"
                      />
                    </div>
                  </>
                )}

                <div className="relative">
                  <Mail className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                  <input
                    type="email"
                    placeholder="Email Address"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    disabled={loading}
                    className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 focus:bg-white disabled:opacity-50"
                  />
                </div>

                <div className="relative">
                  <Lock className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    minLength={6}
                    disabled={loading}
                    className="w-full pl-10 pr-12 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 focus:bg-white disabled:opacity-50"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    disabled={loading}
                    className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 disabled:opacity-50"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>

                {type === "signup" && (
                  <div className="relative">
                    <Lock className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                    <input
                      type={showConfirmPassword ? "text" : "password"}
                      placeholder="Confirm Password"
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      required
                      minLength={6}
                      disabled={loading}
                      className="w-full pl-10 pr-12 py-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-gray-50 focus:bg-white disabled:opacity-50"
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      disabled={loading}
                      className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 disabled:opacity-50"
                    >
                      {showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                    </button>
                  </div>
                )}

                {error && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm"
                  >
                    {error}
                  </motion.div>
                )}

                <button
                  type="submit"
                  disabled={loading}
                  className="w-full bg-gradient-to-r from-blue-600 to-blue-700 text-white py-3 rounded-lg font-semibold hover:from-blue-700 hover:to-blue-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center"
                >
                  {loading ? (
                    <>
                      <svg className="animate-spin h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      {type === "signin" ? "Signing In..." : "Creating Account..."}
                    </>
                  ) : (
                    type === "signin" ? "Log in" : "Sign up"
                  )}
                </button>
              </form>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default AuthModal;

src/components/auth/UpdateProfileModal.t:
"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, User as UserIcon, Loader2, Phone } from "lucide-react";
import Image from "next/image";
import { mwakwaAuth, mwakwaFiles, type MwakwaUser } from "@/lib/mwakwaBackend";

interface UpdateProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: MwakwaUser | null;
}

export default function UpdateProfileModal({ isOpen, onClose, user }: UpdateProfileModalProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    if (user && isOpen) {
      setName(user.display_name || user.full_name || "");
      setPhone(user.phone || "");
      setImageUrl(user.avatar_url || null);
    }
  }, [user, isOpen]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setLoading(true);
    setError("");
    try {
      await mwakwaAuth.updateMe({ display_name: name, phone, avatar_url: imageUrl });
      onClose();
      window.location.reload();
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setError("");
    try {
      const result = await mwakwaFiles.uploadPublic(file);
      const newImageUrl = result.file_url;
      setImageUrl(newImageUrl);
      await mwakwaAuth.updateMe({ avatar_url: newImageUrl });
    } catch (err) {
      setError(`Image upload failed: ${(err as Error).message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 p-4" onClick={onClose}>
          <motion.div initial={{ opacity: 0, scale: 0.95, y: 20 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95, y: 20 }} className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden" onClick={(e) => e.stopPropagation()}>
            <div className="bg-gradient-to-r from-blue-600 to-blue-700 px-6 py-8 relative">
              <button onClick={onClose} className="absolute top-4 right-4 text-white/80 hover:text-white"><X className="w-5 h-5" /></button>
              <h2 className="text-2xl font-bold text-white text-center">Update Profile</h2>
            </div>
            <form onSubmit={handleUpdateProfile} className="p-6 space-y-4">
              <div className="flex flex-col items-center space-y-3">
                <div className="relative w-24 h-24 rounded-full border-4 border-gray-200 overflow-hidden group">
                  {imageUrl ? <Image src={imageUrl} alt="Profile" width={96} height={96} className="object-cover w-full h-full" /> : <div className="w-full h-full bg-gray-400 flex items-center justify-center"><UserIcon className="w-12 h-12 text-white" /></div>}
                  <label htmlFor="avatar-upload" className="absolute inset-0 flex items-center justify-center bg-black/40 text-white opacity-0 group-hover:opacity-100 cursor-pointer text-sm">Change</label>
                  <input id="avatar-upload" type="file" accept="image/*" onChange={handleImageUpload} className="hidden" disabled={loading} />
                </div>
              </div>
              <div className="relative"><UserIcon className="absolute left-3 top-3 h-5 w-5 text-gray-400" /><input value={name} onChange={(e) => setName(e.target.value)} required placeholder="Your Name" className="w-full pl-10 pr-4 py-3 border rounded-lg" /></div>
              <div className="relative"><Phone className="absolute left-3 top-3 h-5 w-5 text-gray-400" /><input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Phone Number" className="w-full pl-10 pr-4 py-3 border rounded-lg" /></div>
              {error && <p className="text-sm text-red-600">{error}</p>}
              <button disabled={loading} className="w-full bg-blue-600 text-white py-3 rounded-lg font-semibold disabled:opacity-50">{loading ? <span className="flex justify-center items-center"><Loader2 className="w-5 h-5 animate-spin mr-2" />Saving...</span> : "Save Changes"}</button>
            </form>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

src/components/checkout/PaymentModal.tsx:
'use client';
import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, CreditCard, Smartphone, ArrowLeft, Globe, Download, Share2, MoreHorizontal, CheckCircle } from 'lucide-react';
import CheckoutButton from '@/components/CheckOutButton';
import type { MwakwaUser as User } from '@/lib/mwakwaBackend';
import { Database } from '@/types/database.types';
import { EnhancedTicket } from '@/types/ticket';
import { getCurrencyInfo } from '@/utils/currency';
import StripeCheckoutButton from '@/components/StripeCheckoutButton';
import { mwakwaData } from '@/lib/mwakwaBackend';
import { base44 } from '@/api/base44Client';

type TicketTypeRow = Database['public']['Tables']['TICKET_TYPES']['Row'];
type PolicySnapshot = { name?: string; buyer_disclosure?: string; description?: string };
type EventPolicyState = { refund_policy_snapshot?: PolicySnapshot | null; cancellation_policy_snapshot?: PolicySnapshot | null };

interface QRCodeProps {
  value: string;
  size: number;
}

const QRCode: React.FC<QRCodeProps> = ({ value, size }) => (
  <div 
    className="bg-gray-100 flex items-center justify-center text-xs text-gray-600 font-mono border-2 border-gray-300"
    style={{ width: size, height: size }}
  >
    QR: {value.slice(-8)}
  </div>
);

const TICKET_COLORS = [
  { bg: '#E53E3E', accent: '#C53030' },
  { bg: '#D53F8C', accent: '#B83280' },
  { bg: '#9F7AEA', accent: '#805AD5' },
  { bg: '#667EEA', accent: '#5A67D8' },
  { bg: '#4299E1', accent: '#3182CE' },
  { bg: '#0BC5EA', accent: '#00B5D8' },
  { bg: '#38B2AC', accent: '#319795' },
  { bg: '#48BB78', accent: '#38A169' },
];

const generateRandomColor = (ticketId: string) => {
  const hash = ticketId.split('').reduce((a, b) => {
    a = ((a << 5) - a) + b.charCodeAt(0);
    return a & a;
  }, 0);

  const index = Math.abs(hash) % TICKET_COLORS.length;
  return TICKET_COLORS[index];
};

const formatCurrency = (amount: number | null | undefined, currencyCode: string | null | undefined): string => {
  const safeAmount = amount || 0;
  const currencyInfo = getCurrencyInfo(currencyCode || undefined);
  const symbol = currencyInfo?.symbol ?? '';

  try {
    return `${symbol}${safeAmount.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
  } catch (e) {
    return `${symbol}${safeAmount.toLocaleString()}`;
  }
};

const formatTicketDate = (dateStr: string) => {
  return new Date(dateStr).toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric'
  });
};

const formatTicketTime = (dateStr: string) => {
  return new Date(dateStr).toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
};

interface TicketCardProps {
  ticket: EnhancedTicket;
  onDownload?: (ticket: EnhancedTicket) => Promise<void>;
  onShare?: (ticket: EnhancedTicket) => Promise<void>;
  onView?: (ticket: EnhancedTicket) => void;
}

const TicketCard: React.FC<TicketCardProps> = ({ ticket, onDownload, onShare, onView }) => {
  const [cardColors] = useState(() => generateRandomColor(ticket.id));

  const handleDownload = async () => {
    if (onDownload) {
      await onDownload(ticket);
    } else {
      alert(`Ticket ${ticket.orderId} download started`);
    }
  };

  const handleShare = async () => {
    if (onShare) {
      await onShare(ticket);
    } else {
      const shareText = `🎫 ${ticket.eventTitle}\n📅 ${formatTicketDate(ticket.eventDate)} at ${formatTicketTime(ticket.eventDate)}\n📍 ${ticket.eventLocation}\n🎟️ Order: ${ticket.orderId}`;

      if (navigator.share) {
        try {
          await navigator.share({
            title: `${ticket.eventTitle} - Ticket`,
            text: shareText,
          });
        } catch (error) {
          if ((error as Error).name !== 'AbortError') {
            navigator.clipboard?.writeText(shareText);
            alert('Ticket details copied to clipboard!');
          }
        }
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(shareText);
        alert('Ticket details copied to clipboard!');
      }
    }
  };

  return (
    <div className="relative max-w-sm mx-auto">
      <div
        className="relative rounded-t-3xl rounded-b-lg overflow-hidden shadow-2xl text-white"
        style={{ backgroundColor: cardColors.bg }}
      >
        <div className="absolute -top-6 left-1/2 transform -translate-x-1/2 w-12 h-12 bg-gray-100 rounded-full"></div>

        <div className="flex justify-between items-start p-4 pt-8">
          <div>
            <div className="text-xs font-medium opacity-90 mb-1">
              {formatTicketDate(ticket.eventDate)}
            </div>
            <div className="text-sm font-bold">
              {formatTicketTime(ticket.eventDate)}
            </div>
          </div>

          <div className="flex items-center space-x-1">
            <button
              onClick={handleShare}
              className="p-1 hover:bg-white hover:bg-opacity-20 rounded-full transition-colors"
              title="Share ticket"
            >
              <Share2 className="w-4 h-4" />
            </button>
            <button
              onClick={handleDownload}
              className="p-1 hover:bg-white hover:bg-opacity-20 rounded-full transition-colors"
              title="Download ticket"
            >
              <Download className="w-4 h-4" />
            </button>
            <button
              onClick={() => onView && onView(ticket)}
              className="p-1 hover:bg-white hover:bg-opacity-20 rounded-full transition-colors"
              title="View details"
            >
              <MoreHorizontal className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="px-4 pb-6">
          <div className="flex justify-between items-start mb-4">
            <div>
              <div className="text-xs opacity-80 mb-1">Ticket Type</div>
              <div className="font-semibold text-sm">{ticket.ticketType}</div>
            </div>
            <div className="text-right">
              <div className="text-xs opacity-80 mb-1">Order ID</div>
              <div className="font-mono text-xs">{ticket.orderId}</div>
            </div>
          </div>

          <div className="mb-4">
            <div className="text-xs opacity-80 mb-1">Venue</div>
            <div className="text-sm leading-snug">
              {ticket.eventLocation}
            </div>
          </div>

          <div className="mb-6">
            <div className="text-xs opacity-80 mb-1">Format</div>
            <div className="text-sm">
              {ticket.eventLocation.toLowerCase().includes('online') || 
               ticket.eventLocation.toLowerCase().includes('virtual') || 
               ticket.eventLocation.toLowerCase().includes('zoom') ? 'Online' : 'In-Person'}
            </div>
          </div>

          <div className="flex justify-center mb-4">
            <div className="bg-white p-3 rounded-lg">
              <QRCode
                value={ticket.qrCode}
                size={100}
              />
            </div>
          </div>

          <div className="text-center">
            <div className="text-sm font-medium opacity-90">
              {ticket.eventTitle}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

type PaymentMethod = 'mobile_money' | 'credit_card' | null;
type Country = {
  code: string;
  name: string;
  flag: string;
  dialCode: string;
  mtnSupported: boolean;
  vodafoneSupported: boolean;
  airtelSupported: boolean;
