  { code: 'RW', name: 'Rwanda', flag: '🇷🇼', dialCode: '250', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'ZM', name: 'Zambia', flag: '🇿🇲', dialCode: '260', mtnSupported: true, vodafoneSupported: false, airtelSupported: true },
  { code: 'BJ', name: 'Benin', flag: '🇧🇯', dialCode: '229', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'CG', name: 'Congo', flag: '🇨🇬', dialCode: '242', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'CI', name: 'Côte d\'Ivoire', flag: '🇨🇮', dialCode: '225', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'GN', name: 'Guinea', flag: '🇬🇳', dialCode: '224', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'LR', name: 'Liberia', flag: '🇱🇷', dialCode: '231', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'SS', name: 'South Sudan', flag: '🇸🇸', dialCode: '211', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'SZ', name: 'Eswatini', flag: '🇸🇿', dialCode: '268', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'AF', name: 'Afghanistan', flag: '🇦🇫', dialCode: '93', mtnSupported: true, vodafoneSupported: false, airtelSupported: false },
  { code: 'YE', name: 'Yemen', flag: '🇾🇪', dialCode: '967', mtnSupported: true, vodafoneSupported: false, airtelSupported: false }
];

interface EnhancedPaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedTicket: TicketTypeRow;
  quantity: number;
  user: User | null;
  eventTitle: string;
  eventDate: string | null;
  eventLocation: string | null;
  eventId?: number;
  eventImage?: string;
  onPaymentSuccess?: (tickets: EnhancedTicket[]) => void;
  eventCurrency: string | null;
}

const EnhancedPaymentModal: React.FC<EnhancedPaymentModalProps> = ({
  isOpen,
  onClose,
  selectedTicket,
  quantity,
  user,
  eventTitle,
  eventDate,
  eventLocation,
  eventId,
  eventImage,
  onPaymentSuccess,
  eventCurrency
}) => {
  const [step, setStep] = useState<'method' | 'details' | 'success'>('method');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(null);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [selectedCountry, setSelectedCountry] = useState<Country>(COUNTRIES[1]);
  const [provider, setProvider] = useState<'mtn' | 'vodafone' | 'airteltigo'>('mtn');
  const [showCountryDropdown, setShowCountryDropdown] = useState(false);
  const [generatedTickets, setGeneratedTickets] = useState<EnhancedTicket[]>([]);
  const [paidPaymentsEnabled, setPaidPaymentsEnabled] = useState(false);
  const [eventPolicies, setEventPolicies] = useState<EventPolicyState | null>(null);
  const [policiesAccepted, setPoliciesAccepted] = useState(false);

  useEffect(() => {
    mwakwaData.platformSettings.filter({}, undefined, 1, 0)
      .then((rows) => setPaidPaymentsEnabled(Boolean(rows?.[0]?.paid_payments_enabled)))
      .catch(() => setPaidPaymentsEnabled(false));
  }, []);

  useEffect(() => {
    if (!isOpen || !eventId) return;
    setPoliciesAccepted(false);
    mwakwaData.events.filter({ id: String(eventId) }, undefined, 1, 0)
      .then((rows) => setEventPolicies(rows?.[0] || null))
      .catch(() => setEventPolicies(null));
  }, [isOpen, eventId]);

  // Discount code states
  const [discountCode, setDiscountCode] = useState('');
  const [discountError, setDiscountError] = useState('');
  const [isValidatingCode, setIsValidatingCode] = useState(false);
  const [appliedDiscount, setAppliedDiscount] = useState<{
    code: string;
    type: 'percentage' | 'fixed' | 'free';
    value: number;
  } | null>(null);

  // Calculate amounts
  const baseAmount = (selectedTicket.price || 0) * quantity;

  const calculateFinalAmount = () => {
    if (!appliedDiscount) return baseAmount;

    if (appliedDiscount.type === 'free') {
      return 0;
    }

    if (appliedDiscount.type === 'percentage') {
      const discountAmount = (baseAmount * appliedDiscount.value) / 100;
      return Math.max(0, baseAmount - discountAmount);
    }

    if (appliedDiscount.type === 'fixed') {
      return Math.max(0, baseAmount - appliedDiscount.value);
    }

    return baseAmount;
  };

  const finalAmount = calculateFinalAmount();
  const discountAmount = baseAmount - finalAmount;
  const isFreeTicket = finalAmount === 0;

  // Validate discount code
  const handleValidateDiscount = async () => {
    if (!discountCode.trim()) {
      setDiscountError('Please enter a discount code');
      return;
    }

    if (!eventId) {
      setDiscountError('Event ID is missing');
      return;
    }

    setIsValidatingCode(true);
    setDiscountError('');

    try {
      const discounts = await mwakwaData.discountCodes.filter({ code: discountCode.toUpperCase(), event_id: String(eventId), is_active: true });
      const discount = discounts[0];

      if (!discount) {
        setAppliedDiscount(null);
        setDiscountError('Invalid discount code');
        return;
      }

      // Check usage limit
      if (discount.max_uses && discount.uses_count >= discount.max_uses) {
        setAppliedDiscount(null);
        setDiscountError('This discount code has reached its usage limit');
        return;
      }

      // Check valid dates
      if (discount.valid_from) {
        const validFrom = new Date(discount.valid_from);
        if (new Date() < validFrom) {
          setAppliedDiscount(null);
          setDiscountError(`This code is not valid until ${validFrom.toLocaleDateString()}`);
          return;
        }
      }

      if (discount.valid_until) {
        const validUntil = new Date(discount.valid_until);
        if (new Date() > validUntil) {
          setAppliedDiscount(null);
          setDiscountError('This discount code has expired');
          return;
        }
      }

      // Apply discount
      setAppliedDiscount({
        code: discount.code,
        type: discount.discount_type,
        value: discount.discount_value,
      });
      setDiscountError('');

      console.log('Discount applied:', {
        type: discount.discount_type,
        value: discount.discount_value,
        baseAmount,
        finalAmount: calculateFinalAmount()
      });

    } catch (error) {
      console.error('Error validating discount code:', error);
      setAppliedDiscount(null);
      setDiscountError('Failed to validate discount code');
    } finally {
      setIsValidatingCode(false);
    }
  };

  const handleRemoveDiscount = () => {
    setDiscountCode('');
    setDiscountError('');
    setAppliedDiscount(null);
  };

  // Handle free checkout (only for 100% free tickets)
  const handleFreeCheckout = async () => {
    if (!user || !eventId) {
      setDiscountError('Missing user or event information');
      return;
    }

    if (!appliedDiscount) {
      setDiscountError('Please apply a discount code first');
      return;
    }

    console.log('Attempting free checkout:', {
      discountType: appliedDiscount.type,
      discountValue: appliedDiscount.value,
      finalAmount,
      isFreeTicket
    });

    if (!isFreeTicket) {
      setDiscountError('This discount requires payment. Please use the payment options below.');
      return;
    }
    if (!policiesAccepted) {
      setDiscountError('Please accept the ticket, refund and cancellation terms before checkout.');
      return;
    }

    try {
      setIsValidatingCode(true);
      setDiscountError('');

      interface GeneratedTicket {
        id: number;
        qr_code_data: string;
        created_at: string;
        user_id: string;
        event_id: number;
        ticket_type_id: number;
        quantity: string;
        unit_price: number;
        total: number;
        ticket_status: string;
      }

      const response = await base44.functions.invoke('free-checkout', { event_id: String(eventId), ticket_type_id: String(selectedTicket.id), quantity, discount_code: discountCode });
      const freeResult = ((response as { data?: { tickets?: GeneratedTicket[] } }).data || response) as { tickets?: GeneratedTicket[] };
      const tickets = freeResult.tickets;
      if (!tickets || tickets.length === 0) throw new Error('No tickets were generated');



      const enhancedTickets: EnhancedTicket[] = (tickets as GeneratedTicket[]).map((ticket) => ({
        id: ticket.id.toString(),
        orderId: ticket.qr_code_data,
        eventTitle: eventTitle,
        eventDate: eventDate || new Date().toISOString(),
        eventLocation: eventLocation || 'TBA',
        ticketType: selectedTicket.name || 'General Admission',
        qrCode: ticket.qr_code_data,
        status: 'confirmed',
        ticketStatus: 'active',
        eventId: eventId.toString(),
        quantity: 1,
        totalPrice: 0,
        purchaseDate: ticket.created_at || new Date().toISOString(),
        userName: user?.display_name || user?.full_name || user?.email || 'Guest',
      }));


      await handlePaymentSuccess(enhancedTickets);

    } catch (error) {
      console.error('Error generating free tickets:', error);
      setDiscountError(
        error instanceof Error 
          ? `Failed to generate tickets: ${error.message}` 
          : 'Failed to generate tickets. Please try again.'
      );
    } finally {
      setIsValidatingCode(false);
    }
  };

  const handleMethodSelect = (method: PaymentMethod) => {
    if (!policiesAccepted) {
      setDiscountError('Please accept the ticket, refund and cancellation terms before selecting payment.');
      return;
    }
    setPaymentMethod(method);
    setStep('details');
  };

  const handleBackToMethods = () => {
    if (step === 'success') {
      setStep('method');
      setPaymentMethod(null);
      setPhoneNumber('');
      setGeneratedTickets([]);
    } else {
      setStep('method');
      setPaymentMethod(null);
    }
  };

  const handlePaymentSuccess = async (tickets: EnhancedTicket[]) => {
    setGeneratedTickets(tickets);
    setStep('success');


    if (onPaymentSuccess) {
      onPaymentSuccess(tickets);
    }
  };

  const handlePaymentError = (error: string) => {
    alert(`Payment failed: ${error}`);
  };

  const handleCloseModal = () => {
    onClose();
    setTimeout(() => {
      setStep('method');
      setPaymentMethod(null);
      setPhoneNumber('');
      setGeneratedTickets([]);
      setDiscountCode('');
      setDiscountError('');
      setAppliedDiscount(null);
    }, 300);
  };

  const formatPhoneNumber = (value: string) => {
    const cleaned = value.replace(/\D/g, '');

    if (cleaned.length >= 6) {
      return `${cleaned.slice(0, 3)} ${cleaned.slice(3, 6)} ${cleaned.slice(6)}`;
    } else if (cleaned.length >= 3) {
      return `${cleaned.slice(0, 3)} ${cleaned.slice(3)}`;
    }
    return cleaned;
  };

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatPhoneNumber(e.target.value);
    setPhoneNumber(formatted);
  };

  const getFullPhoneNumber = () => {
    const cleaned = phoneNumber.replace(/\D/g, '');
    return `${selectedCountry.dialCode}${cleaned}`;
  };

  const getAvailableProviders = () => {
    const providers = [];
    if (selectedCountry.mtnSupported) {
      providers.push({ id: 'mtn', name: 'MTN', color: 'border-yellow-400 bg-yellow-50 text-yellow-800' });
    }
    if (selectedCountry.vodafoneSupported) {
      providers.push({ id: 'vodafone', name: 'Vodafone', color: 'border-red-400 bg-red-50 text-red-800' });
    }
    if (selectedCountry.airtelSupported) {
      providers.push({ id: 'airteltigo', name: 'Airtel', color: 'border-green-400 bg-green-50 text-green-800' });
    }
    return providers;
  };

  const handleCountrySelect = (country: Country) => {
    setSelectedCountry(country);
    setShowCountryDropdown(false);
    setPhoneNumber('');

    const availableProviders = getAvailableProviders();
    if (availableProviders.length > 0) {
      const mtnProvider = availableProviders.find(p => p.id === 'mtn');
      setProvider((mtnProvider?.id || availableProviders[0].id) as 'mtn' | 'vodafone' | 'airteltigo');
    }
  };

  const isPhoneNumberValid = () => {
    const cleaned = phoneNumber.replace(/\D/g, '');
    return cleaned.length >= 8 && cleaned.length <= 10;
  };

  const handleTicketDownload = async (ticket: EnhancedTicket) => {
    alert(`Downloading ticket ${ticket.orderId}...`);
  };

  const handleTicketShare = async (ticket: EnhancedTicket) => {
  };

  const handleTicketView = (ticket: EnhancedTicket) => {
    alert(`Viewing details for ${ticket.orderId}`);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4"
          onClick={handleCloseModal}
        >
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
            className="bg-white rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="sticky top-0 bg-white border-b border-gray-200 p-4 rounded-t-2xl z-10">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  {step !== 'method' && (
                    <button
                      onClick={handleBackToMethods}
                      className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                    >
                      <ArrowLeft className="w-5 h-5 text-gray-600" />
                    </button>
                  )}
                  <h2 className="text-xl font-bold text-gray-900">
                    {step === 'method' && 'Payment Method'}
                    {step === 'details' && 'Payment Details'}
                    {step === 'success' && 'Your Tickets'}
                  </h2>
                </div>
                <button
                  onClick={handleCloseModal}
                  className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                >
                  <X className="w-5 h-5 text-gray-600" />
                </button>
              </div>
            </div>

            <div className="p-6">
              {(step === 'method' || step === 'details') && (
                <div className="bg-gray-50 rounded-xl p-4 mb-6">
                  <h3 className="font-semibold text-gray-900 mb-2">Order Summary</h3>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">Event</span>
                      <span className="font-medium text-gray-900">{eventTitle}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Ticket</span>
                      <span className="font-medium text-gray-900">{selectedTicket.name}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Quantity</span>
                      <span className="font-medium text-gray-900">{quantity}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Price per ticket</span>
                      <span className="font-medium text-gray-900">
                        {formatCurrency(selectedTicket.price as unknown as number, eventCurrency)}
                      </span>
                    </div>

                    {appliedDiscount && (
                      <div className="flex justify-between text-green-600">
                        <span>Discount ({appliedDiscount.code})</span>
                        <span className="font-medium">
                          -{appliedDiscount.type === 'percentage' 
                            ? `${appliedDiscount.value}%` 
                            : formatCurrency(discountAmount, eventCurrency)}
                        </span>
                      </div>
                    )}

                    <hr className="my-2" />

                    <div className="flex justify-between text-lg font-bold">
                      <span>Total</span>
                      <span className={appliedDiscount ? 'text-green-600' : 'text-blue-600'}>
                        {appliedDiscount && baseAmount !== finalAmount && (
                          <span className="text-sm text-gray-400 line-through mr-2">
                            {formatCurrency(baseAmount, eventCurrency)}
                          </span>
                        )}
                        {formatCurrency(finalAmount, eventCurrency)}
                      </span>
                    </div>
                  </div>
                </div>
              )}

              {(step === 'method' || step === 'details') && eventPolicies && (
                <div className="border border-gray-200 rounded-xl p-4 mb-5 text-sm">
                  <h4 className="font-semibold text-gray-900 mb-2">Ticket policies</h4>
                  {eventPolicies.refund_policy_snapshot && <div className="mb-3"><p className="font-medium">{eventPolicies.refund_policy_snapshot.name}</p><p className="text-gray-600">{eventPolicies.refund_policy_snapshot.buyer_disclosure || eventPolicies.refund_policy_snapshot.description}</p></div>}
                  {eventPolicies.cancellation_policy_snapshot && <div><p className="font-medium">Cancellation & postponement</p><p className="text-gray-600">{eventPolicies.cancellation_policy_snapshot.buyer_disclosure || eventPolicies.cancellation_policy_snapshot.description}</p></div>}
                  <label className="flex items-start gap-2 mt-4 font-medium"><input type="checkbox" className="mt-1" checked={policiesAccepted} onChange={e => setPoliciesAccepted(e.target.checked)} /><span>I accept these event-specific ticket terms and Mwakwa&apos;s applicable platform terms.</span></label>
                </div>
              )}

              {step === 'method' && (
                <motion.div
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  className="space-y-4"
                >
                  {/* Discount Code Section */}
                  <div className="bg-gradient-to-br from-green-50 to-emerald-50 border-2 border-green-200 rounded-xl p-4 mb-4">
                    <div className="flex items-center gap-2 mb-3">
                      <div className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center">
                        <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                      </div>
                      <h4 className="font-semibold text-gray-900">Have a Discount Code?</h4>
                    </div>

                    {!appliedDiscount ? (
                      <>
                        <p className="text-sm text-gray-600 mb-3">
                          Enter your discount code to save on tickets
                        </p>
                        <div className="flex gap-2">
                          <input
                            type="text"
                            value={discountCode}
                            onChange={(e) => {
                              setDiscountCode(e.target.value.toUpperCase());
                              setDiscountError('');
                            }}
                            onKeyPress={(e) => e.key === 'Enter' && handleValidateDiscount()}
                            placeholder="Enter code"
                            className="flex-1 border-2 border-gray-300 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500 uppercase font-mono text-base font-bold text-gray-900"
                            disabled={isValidatingCode}
                          />
                          <button
                            onClick={handleValidateDiscount}
                            disabled={isValidatingCode || !discountCode.trim()}
                            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg font-medium disabled:bg-gray-300 disabled:cursor-not-allowed"
                          >
                            {isValidatingCode ? 'Checking...' : 'Apply'}
                          </button>
                        </div>
                        {discountError && (
                          <p className="text-red-600 text-xs mt-2">{discountError}</p>
                        )}
                      </>
                    ) : (
                      <div className="space-y-3">
                        <div className="bg-white rounded-lg p-3 border border-green-200">
                          <div className="flex items-center justify-between mb-2">
                            <span className="font-bold text-green-800">Code -{appliedDiscount.code}- Applied!</span>
                            <button onClick={handleRemoveDiscount} className="text-gray-500 text-xs">
                              Remove
                            </button>
                          </div>

                          {isFreeTicket ? (
                            <p className="text-sm text-green-700">
                              ✨ You are getting {quantity} free ticket{quantity > 1 ? 's' : ''}!
                            </p>
                          ) : (
                            <p className="text-sm text-green-700">
                              ✨ Saving {formatCurrency(discountAmount, eventCurrency)}
                              {appliedDiscount.type === 'percentage' && ` (${appliedDiscount.value}% off)`}
                            </p>
                          )}
                        </div>

                        {isFreeTicket && (
                          <button
                            onClick={handleFreeCheckout}
                            disabled={isValidatingCode || !policiesAccepted}
                            className="w-full bg-green-600 hover:bg-green-700 text-white py-3 px-4 rounded-lg font-bold"
                          >
                            {isValidatingCode ? 'Generating...' : 'Get Free Tickets'}
                          </button>
                        )}
                      </div>
                    )}
                  </div>

                  {/* Payment Options - Show when no free ticket */}
                  {!isFreeTicket && paidPaymentsEnabled && (
                    <>
                      <div className="relative my-6">
                        <div className="absolute inset-0 flex items-center">
