"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { mwakwaAuth, mwakwaData, type MwakwaUser } from "@/lib/mwakwaBackend";
import AuthModal from "@/components/auth/AuthModal";
import { useRouter } from "next/navigation";
import { ChevronDown, User as UserIcon, LogOut } from "lucide-react";

type NavItem = { id?: string; label: string; url: string; is_enabled?: boolean; requires_auth?: boolean };
type BrandConfig = { brand_name?: string; logo_url?: string; primary_color?: string; secondary_color?: string; background_color?: string; text_color?: string };

const Header = () => {
  const router = useRouter();
  const [user, setUser] = useState<MwakwaUser | null>(null);
  const [showSignIn, setShowSignIn] = useState(false);
  const [showSignUp, setShowSignUp] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [navItems, setNavItems] = useState<NavItem[] | null>(null);
  const [navLoaded, setNavLoaded] = useState(false);
  const [brand, setBrand] = useState<BrandConfig | null>(null);
  const isAdmin = user?.role === "admin";

  useEffect(() => {
    const getUser = async () => {
      setUser(await mwakwaAuth.me());
    };
    getUser();
    Promise.all([
      mwakwaData.navigationItems.filter({ location: "header" }, "sort_order", 50, 0),
      mwakwaData.brandSettings.filter({}, undefined, 1, 0),
    ]).then(([nav, brands]) => { setNavItems(nav as unknown as NavItem[]); setBrand((brands?.[0] || null) as BrandConfig | null); }).catch(() => { setNavItems(null); }).finally(() => setNavLoaded(true));
  }, []);

  useEffect(() => {
    if (!brand) return;
    const root = document.documentElement;
    const configured = brand;
    if (configured.primary_color) root.style.setProperty("--mwakwa-primary", configured.primary_color);
    if (configured.secondary_color) root.style.setProperty("--mwakwa-secondary", configured.secondary_color);
    if (configured.background_color) root.style.setProperty("--mwakwa-background", configured.background_color);
    if (configured.text_color) root.style.setProperty("--mwakwa-text", configured.text_color);
  }, [brand]);

  const handleSignOut = async () => {
    await mwakwaAuth.logout("/");
    setUser(null);
    setIsMobileMenuOpen(false);
    setIsProfileDropdownOpen(false);
    router.push("/");
  };

  const handleAuthSuccess = () => {
    setShowSignIn(false);
    setShowSignUp(false);
    router.push("/profile");
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const toggleProfileDropdown = () => {
    setIsProfileDropdownOpen(!isProfileDropdownOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      <header className="w-full bg-white shadow-md px-6 py-3 sticky top-0 z-50">
        <div className="flex items-center justify-between relative">
          {/* Left Nav (desktop) */}
          <nav className="hidden md:flex items-center space-x-6 text-black">
            {(navLoaded ? (navItems ?? []) : [
              { label: "Home", url: "/" }, { label: "Events", url: "/events" }, { label: "Organiser Space", url: "/organiser" }
            ]).filter((item: NavItem) => item.is_enabled !== false && (!item.requires_auth || !!user)).map((item: NavItem) => (
              <Link key={item.id || item.url} href={item.url} className="hover:cms-primary-text">{item.label}</Link>
            ))}
          </nav>

          {/* Logo Center */}
          <div className="absolute left-1/2 transform -translate-x-1/2">
            <Link href="/">
              <Image
                src={brand?.logo_url || "/images/logo.png"}
                alt={`${brand?.brand_name || "Mwakwa"} Logo`}
                width={110}
                height={35}
                className="mx-auto"
              />
            </Link>
          </div>

          {/* Right Nav (desktop) */}
          <nav className="hidden md:flex items-center space-x-4 text-black">
            {user ? (
              <div className="relative">
                <button
                  onClick={toggleProfileDropdown}
                  className="flex items-center space-x-2 px-3 py-1.5 rounded-full bg-gray-200 text-sm focus:outline-none"
                >
                  <span className="w-7 h-7 rounded-full overflow-hidden">
                    {user.avatar_url ? (
                      <Image
                        src={user.avatar_url!}
                        alt="Profile Picture"
                        width={28}
                        height={28}
                        className="object-cover"
                      />
                    ) : (
                      <div className="w-7 h-7 bg-gray-400 rounded-full flex items-center justify-center">
                        <UserIcon className="w-4 h-4 text-white" />
                      </div>
                    )}
                  </span>
                  <span>{user.display_name || user.full_name || user.email}</span>
                  <ChevronDown className={`w-4 h-4 transition-transform ${isProfileDropdownOpen ? 'rotate-180' : 'rotate-0'}`} />
                </button>

                {isProfileDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-48 bg-white shadow-lg rounded-lg overflow-hidden ring-1 ring-black ring-opacity-5">
                    <div className="py-1">
                      <Link href="/profile" onClick={() => setIsProfileDropdownOpen(false)} className="flex items-center px-4 py-2 text-sm text-gray-700 hover:bg-gray-100">
                        <UserIcon className="w-4 h-4 mr-2" />
                        Manage Profile
                      </Link>
                      {isAdmin && <Link href="/admin/cms" onClick={() => setIsProfileDropdownOpen(false)} className="flex items-center px-4 py-2 text-sm text-gray-700 hover:bg-gray-100">CMS</Link>}
                      <button
                        onClick={handleSignOut}
                        className="w-full flex items-center px-4 py-2 text-sm text-red-600 hover:bg-gray-100"
                      >
                        <LogOut className="w-4 h-4 mr-2" />
                        Sign Out
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <>
                <button
                  onClick={() => setShowSignUp(true)}
                  className="px-3 py-1.5 cms-primary-bg text-white rounded-full text-sm opacity-95 hover:opacity-100"
                >
                  Sign Up
                </button>
                <button
                  onClick={() => setShowSignIn(true)}
                  className="px-3 py-1.5 cms-primary-text rounded-full border text-sm hover:bg-gray-50" style={{ borderColor: "var(--mwakwa-primary)" }}
                >
                  Sign In
                </button>
              </>
            )}
          </nav>

          {/* Mobile Menu Button */}
          <div className="md:hidden">
            <button
              onClick={toggleMobileMenu}
              className="p-2 rounded-md text-gray-700 hover:cms-primary-text hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
            >
              <span className="sr-only">Open main menu</span>
              <div className="w-6 h-6 flex flex-col justify-center items-center">
                <span
                  className={`bg-current h-0.5 w-5 rounded-sm transform transition-all duration-300 ease-in-out ${
                    isMobileMenuOpen ? 'rotate-45 translate-y-1' : '-translate-y-1'
                  }`}
                />
                <span
                  className={`bg-current h-0.5 w-5 rounded-sm transform transition-all duration-300 ease-in-out ${
                    isMobileMenuOpen ? '-rotate-45 -translate-y-1' : 'translate-y-1'
                  }`}
                />
              </div>
            </button>
          </div>
        </div>

        {/* Mobile Menu - Full Screen */}
        {isMobileMenuOpen && (
          <div className="md:hidden fixed inset-0 top-16 bg-white z-40 transform transition-all duration-300 ease-in-out">
            <div className="h-full flex flex-col">
              <div className="flex-1 flex flex-col justify-center px-4">
                <div className="flex flex-col items-center space-y-8">
                  {(navLoaded ? (navItems ?? []) : [
                    { label: "Home", url: "/" }, { label: "Events", url: "/events" }, { label: "Organiser Space", url: "/organiser" }
                  ]).filter((item: NavItem) => item.is_enabled !== false && (!item.requires_auth || !!user)).map((item: NavItem) => (
                    <Link key={item.id || item.url} href={item.url} onClick={closeMobileMenu} className="text-gray-700 hover:cms-primary-text font-medium text-2xl py-3">
                      {item.label}
                    </Link>
                  ))}
                </div>
              </div>

              {/* Auth Section - Bottom */}
              <div className="pb-8 px-4">
                {user ? (
                  <div className="flex flex-col items-center space-y-4">
                    <span className="flex items-center space-x-2 text-gray-600 font-semibold text-lg">
                      <span className="w-8 h-8 rounded-full overflow-hidden">
                        {user.avatar_url ? (
                          <Image
                            src={user.avatar_url!}
                            alt="Profile"
                            width={32}
                            height={32}
                            className="object-cover"
                          />
                        ) : (
                          <div className="w-8 h-8 bg-gray-400 rounded-full flex items-center justify-center">
                            <UserIcon className="w-5 h-5 text-white" />
                          </div>
                        )}
                      </span>
                      <span>{user.display_name || user.full_name || user.email}</span>
                    </span>
                    <Link
                      href="/profile"
                      onClick={closeMobileMenu}
                      className="px-8 py-3 cms-primary-bg text-white rounded-full text-lg opacity-95 hover:opacity-100 w-full max-w-sm text-center"
                    >
                      Manage Profile
                    </Link>
                    {isAdmin && <Link href="/admin/cms" onClick={closeMobileMenu} className="px-8 py-3 cms-primary-text rounded-full border text-lg hover:bg-gray-50 w-full max-w-sm text-center" style={{ borderColor: "var(--mwakwa-primary)" }}>CMS</Link>}
                    <button
                      onClick={handleSignOut}
                      className="px-8 py-3 text-red-600 rounded-full border border-red-600 text-lg hover:bg-red-50 w-full max-w-sm"
                    >
                      Sign Out
                    </button>
                  </div>
                ) : (
                  <div className="flex flex-col items-center space-y-4">
                    <button
                      onClick={() => {
                        setShowSignUp(true);
                        closeMobileMenu();
                      }}
                      className="px-8 py-3 cms-primary-bg text-white rounded-full text-lg opacity-95 hover:opacity-100 w-full max-w-sm"
                    >
                      Sign Up
                    </button>
                    <button
                      onClick={() => {
                        setShowSignIn(true);
                        closeMobileMenu();
                      }}
                      className="px-8 py-3 cms-primary-text rounded-full border text-lg hover:bg-gray-50 w-full max-w-sm" style={{ borderColor: "var(--mwakwa-primary)" }}
                    >
                      Sign In
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </header>

      <AuthModal
        type="signin"
        isOpen={showSignIn}
        onClose={() => setShowSignIn(false)}
        onSuccess={handleAuthSuccess}
      />

      <AuthModal
        type="signup"
        isOpen={showSignUp}
        onClose={() => setShowSignUp(false)}
        onSuccess={handleAuthSuccess}
      />
    </>
  );
};

export default Header;

