// Updated CreateEventModal with proper currency handling, navigation, and fee disclaimer
'use client';
import React, { useEffect, useState } from 'react';
import { mwakwaData, mwakwaFiles, type MwakwaUser } from '@/lib/mwakwaBackend';

interface CreateEventModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  user: MwakwaUser | null;
}

interface EventFormData {
  title: string;
  description: string;
  date: string;
  time: string;
  location: string;
  venue: string;
  category: string;
  currency: string;
  image: File | null;
  ticketTypes: TicketType[];
  eventStatus: 'draft' | 'published';
}

interface TicketType {
  id: string;
  name: string;
  price: number;
  quantity: number;
  description: string;
  format: 'in-person' | 'online';
}

interface Currency {
  code: string;
  symbol: string;
  name: string;
  flag: string;
}

const CreateEventModal: React.FC<CreateEventModalProps> = ({ 
  isOpen, 
  onClose, 
  onSuccess,
  user
}) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [formData, setFormData] = useState<EventFormData>({
    title: '',
    description: '',
    date: '',
    time: '',
    location: '',
    venue: '',
    category: '',
    currency: 'XOF', // Default to West African CFA Franc
    image: null,
    ticketTypes: [],
    eventStatus: 'draft'
  });

  const categories = [
    'Music & Entertainment',
    'Business & Networking',
    'Technology & Innovation',
    'Arts & Culture',
    'Sports & Fitness',
    'Food & Dining',
    'Education & Workshops',
    'Community & Social',
    'Other'
  ];

  const currencies: Currency[] = [
    // West African CFA Franc (primary default)
    { code: 'XOF', symbol: 'CFA', name: 'West African CFA Franc', flag: '🇸🇳' },

    // Other major African currencies
    { code: 'GHS', symbol: '₵', name: 'Ghanaian Cedi', flag: '🇬🇭' },
    { code: 'NGN', symbol: '₦', name: 'Nigerian Naira', flag: '🇳🇬' },
    { code: 'XAF', symbol: 'FCFA', name: 'Central African CFA Franc', flag: '🇨🇲' },
    { code: 'ZAR', symbol: 'R', name: 'South African Rand', flag: '🇿🇦' },
    { code: 'KES', symbol: 'KSh', name: 'Kenyan Shilling', flag: '🇰🇪' },
    { code: 'UGX', symbol: 'USh', name: 'Ugandan Shilling', flag: '🇺🇬' },
    { code: 'TZS', symbol: 'TSh', name: 'Tanzanian Shilling', flag: '🇹🇿' },
    { code: 'ETB', symbol: 'Br', name: 'Ethiopian Birr', flag: '🇪🇹' },
    { code: 'EGP', symbol: '£', name: 'Egyptian Pound', flag: '🇪🇬' },
    { code: 'MAD', symbol: 'DH', name: 'Moroccan Dirham', flag: '🇲🇦' },
    { code: 'BWP', symbol: 'P', name: 'Botswanan Pula', flag: '🇧🇼' },

    // International currencies
    { code: 'USD', symbol: '$', name: 'US Dollar', flag: '🇺🇸' },
    { code: 'EUR', symbol: '€', name: 'Euro', flag: '🇪🇺' },
    { code: 'GBP', symbol: '£', name: 'British Pound', flag: '🇬🇧' }
  ];

  const selectedCurrency = currencies.find(c => c.code === formData.currency) || currencies[0];

  const handleInputChange = (field: keyof EventFormData, value: string | 'draft' | 'published') => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setError('');
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    setFormData(prev => ({ ...prev, image: file }));
  };

  const addTicketType = () => {
    const newTicket: TicketType = {
      id: Date.now().toString(),
      name: '',
      price: 0,
      quantity: 0,
      description: '',
      format: 'in-person'
    };
    setFormData(prev => ({
      ...prev,
      ticketTypes: [...prev.ticketTypes, newTicket]
    }));
  };

  const updateTicketType = (id: string, field: keyof TicketType, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      ticketTypes: prev.ticketTypes.map(ticket =>
        ticket.id === id ? { ...ticket, [field]: value } : ticket
      )
    }));
  };

  const removeTicketType = (id: string) => {
    setFormData(prev => ({
      ...prev,
      ticketTypes: prev.ticketTypes.filter(ticket => ticket.id !== id)
    }));
  };

  // Step validation functions
  const isStepValid = (): boolean => {
    switch (currentStep) {
      case 1:
        return formData.title.trim() !== '' && 
               formData.description.trim() !== '' && 
               formData.category.trim() !== '';
      case 2:
        return formData.date.trim() !== '' && 
               formData.time.trim() !== '' && 
               formData.location.trim() !== '';
      case 3:
        return true; // Tickets are optional
      case 4:
        return true; // Just choosing publish status
      default:
        return false;
    }
  };

  const nextStep = () => {
    if (currentStep < 4 && isStepValid()) {
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const uploadEventImage = async (): Promise<string | null> => {
    if (!formData.image) return null;
    try {
      const result = await mwakwaFiles.uploadPublic(formData.image);
      return result.file_url;
    } catch (error) {
      console.error('Error uploading image:', error);
      return null;
    }
  };

  type PolicyOption = { id: string; is_active?: boolean; is_default?: boolean; name?: string; buyer_disclosure?: string; description?: string; organizer_liability?: boolean; refund_window_hours?: number; refund_percentage?: number; [key: string]: unknown };
  const [cancellationPolicies, setCancellationPolicies] = useState<PolicyOption[]>([]);
  const [selectedCancellationPolicyId, setSelectedCancellationPolicyId] = useState('');
  const [refundPolicies, setRefundPolicies] = useState<PolicyOption[]>([]);
  const [selectedRefundPolicyId, setSelectedRefundPolicyId] = useState('');

  useEffect(() => {
    if (!isOpen) return;
    Promise.all([
      mwakwaData.cancellationPolicies.list('sort_order', 50, 0),
      mwakwaData.refundPolicies.list('sort_order', 50, 0),
    ]).then(([cancellationRows, refundRows]) => {
      const activeCancellation = (cancellationRows as PolicyOption[]).filter((r) => r.is_active !== false);
      const activeRefunds = (refundRows as PolicyOption[]).filter((r) => r.is_active !== false);
      setCancellationPolicies(activeCancellation);
      setRefundPolicies(activeRefunds);
      const preferredCancellation = activeCancellation.find((r) => r.is_default) || activeCancellation[0];
      const preferredRefund = activeRefunds.find((r) => r.is_default) || activeRefunds[0];
      setSelectedCancellationPolicyId(prev => prev || preferredCancellation?.id || '');
      setSelectedRefundPolicyId(prev => prev || preferredRefund?.id || '');
    }).catch(() => { setCancellationPolicies([]); setRefundPolicies([]); });
  }, [isOpen]);

  const handleSubmit = async () => {
    if (!user) {
      setError('User not authenticated');
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      const imageUrl = formData.image ? await uploadEventImage() : null;
      const selectedPolicy = cancellationPolicies.find(p => p.id === selectedCancellationPolicyId);
      if (!selectedPolicy) throw new Error('Please select an event cancellation policy');
      const selectedRefundPolicy = refundPolicies.find(p => p.id === selectedRefundPolicyId);
      if (!selectedRefundPolicy) throw new Error('Please select a buyer refund policy');
      const policySnapshot = {
        id: selectedPolicy.id,
        template_code: selectedPolicy.template_code,
        name: selectedPolicy.name,
        description: selectedPolicy.description,
        event_cancellation_refund_mode: selectedPolicy.event_cancellation_refund_mode,
        postponement_mode: selectedPolicy.postponement_mode,
        postponement_refund_window_hours: selectedPolicy.postponement_refund_window_hours,
        organizer_liability: selectedPolicy.organizer_liability,
        buyer_disclosure: selectedPolicy.buyer_disclosure,
        snapshotted_at: new Date().toISOString(),
      };
      const refundPolicySnapshot = {
        id: selectedRefundPolicy.id,
        template_code: selectedRefundPolicy.template_code,
        name: selectedRefundPolicy.name,
        description: selectedRefundPolicy.description,
        refunds_allowed: selectedRefundPolicy.refunds_allowed,
        voluntary_cancellation_mode: selectedRefundPolicy.voluntary_cancellation_mode,
        cutoff_hours_before_event: selectedRefundPolicy.cutoff_hours_before_event,
        refund_percent: selectedRefundPolicy.refund_percent,
        buyer_fee_refundable: selectedRefundPolicy.buyer_fee_refundable,
        processor_fee_refundable: selectedRefundPolicy.processor_fee_refundable,
        buyer_disclosure: selectedRefundPolicy.buyer_disclosure,
        snapshotted_at: new Date().toISOString(),
      };
      const eventData = await mwakwaData.events.create({
        title: formData.title,
        description: formData.description,
        event_date: formData.date,
        start_time: formData.time,
        location_name: formData.location,
        address: formData.venue,
        organizer_id: user.id,
        organizer_name: user.display_name || user.full_name || user.email,
        event_status: formData.eventStatus,
        currency: formData.currency,
        currency_symbol: selectedCurrency.symbol,
        images: imageUrl ? [imageUrl] : [],
        is_featured: false,
        is_sponsored: false,
        cancellation_policy_id: selectedPolicy.id,
        cancellation_policy_snapshot: policySnapshot,
        cancellation_policy_accepted_at: new Date().toISOString(),
        refund_policy_id: selectedRefundPolicy.id,
        refund_policy_snapshot: refundPolicySnapshot,
        refund_policy_accepted_at: new Date().toISOString(),
      });
      const eventId = eventData.id;

      for (const ticketType of formData.ticketTypes) {
        await mwakwaData.ticketTypes.create({
          event_id: eventId,
          organizer_id: user.id,
          name: ticketType.name,
          description: ticketType.description,
          price: ticketType.price,
          max_quantity: ticketType.quantity,
          currency: formData.currency,
          currency_symbol: selectedCurrency.symbol,
          format: ticketType.format,
          is_active: true,
        });
      }

      // Reset form
      setFormData({
        title: '',
        description: '',
        date: '',
        time: '',
        location: '',
        venue: '',
        category: '',
        currency: 'XOF',
        image: null,
        ticketTypes: [],
        eventStatus: 'draft'
      });

      setCurrentStep(1);
      onSuccess();

    } catch (error) {
      console.error('Error creating event:', error);
      setError(error instanceof Error ? error.message : 'Failed to create event');
    } finally {
      setIsLoading(false);
    }
  };
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4">
        <div className="fixed inset-0 bg-black opacity-50" onClick={onClose}></div>

        <div className="relative bg-white rounded-lg shadow-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
          {/* Header */}
          <div className="flex justify-between items-center p-6 border-b border-gray-200">
            <div>
              <h2 className="text-2xl font-bold text-gray-900">Create New Event</h2>
              <p className="text-sm text-gray-600">Step {currentStep} of 4</p>
            </div>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Progress Bar */}
          <div className="px-6 py-4 bg-gray-50">
            <div className="flex items-center">
              {[1, 2, 3, 4].map((step) => (
                <React.Fragment key={step}>
                  <div className={`flex items-center justify-center w-8 h-8 rounded-full text-sm font-medium ${
                    step <= currentStep ? 'bg-blue-600 text-white' : 'bg-gray-300 text-gray-600'
                  }`}>
                    {step}
                  </div>
                  {step < 4 && (
                    <div className={`flex-1 h-1 mx-2 ${
                      step < currentStep ? 'bg-blue-600' : 'bg-gray-300'
                    }`}></div>
                  )}
                </React.Fragment>
              ))}
            </div>
            <div className="flex justify-between mt-2 text-xs text-gray-600">
              <span>Event Details</span>
              <span>Date & Location</span>
              <span>Tickets</span>
              <span>Publish</span>
            </div>
          </div>

          {/* Error Display */}
          {error && (
            <div className="mx-6 mt-4 p-4 bg-red-50 border border-red-200 rounded-lg">
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          {/* Form Content */}
          <div className="p-6">
            {currentStep === 1 && (
              <div className="space-y-6">
                <h3 className="text-lg font-semibold text-gray-900">Event Details</h3>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Event Title *
                  </label>
                  <input
                    type="text"
                    value={formData.title}
                    onChange={(e) => handleInputChange('title', e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Enter event title"
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Category *
                    </label>
                    <select
                      value={formData.category}
                      onChange={(e) => handleInputChange('category', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    >
                      <option value="">Select a category</option>
                      {categories.map((category) => (
                        <option key={category} value={category}>{category}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Currency *
                    </label>
                    <select
                      value={formData.currency}
                      onChange={(e) => handleInputChange('currency', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    >
                      <optgroup label="West/Central African Currencies">
                        {currencies.filter(c => ['XOF', 'XAF'].includes(c.code)).map((currency) => (
                          <option key={currency.code} value={currency.code}>
                            {currency.flag} {currency.symbol} - {currency.name}
                          </option>
                        ))}
                      </optgroup>
                      <optgroup label="Other African Currencies">
                        {currencies.filter(c => !['XOF', 'XAF', 'USD', 'EUR', 'GBP'].includes(c.code)).map((currency) => (
                          <option key={currency.code} value={currency.code}>
                            {currency.flag} {currency.symbol} - {currency.name}
                          </option>
                        ))}
                      </optgroup>
                      <optgroup label="International Currencies">
                        {currencies.filter(c => ['USD', 'EUR', 'GBP'].includes(c.code)).map((currency) => (
                          <option key={currency.code} value={currency.code}>
                            {currency.flag} {currency.symbol} - {currency.name}
                          </option>
                        ))}
                      </optgroup>
                    </select>
                    <p className="text-xs text-gray-500 mt-1">
                      Selected: {selectedCurrency.flag} {selectedCurrency.name}
                    </p>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Description *
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    rows={4}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Describe your event..."
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Event Image
                  </label>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <p className="text-xs text-gray-500 mt-1">Upload an image for your event (JPG, PNG, up to 5MB)</p>
                </div>
              </div>
            )}

            {currentStep === 2 && (
              <div className="space-y-6">
                <h3 className="text-lg font-semibold text-gray-900">Date & Location</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Event Date *
                    </label>
                    <input
                      type="date"
                      value={formData.date}
                      onChange={(e) => handleInputChange('date', e.target.value)}
                      min={new Date().toISOString().split('T')[0]}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Event Time *
                    </label>
                    <input
                      type="time"
                      value={formData.time}
                      onChange={(e) => handleInputChange('time', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Location/City *
                  </label>
                  <input
                    type="text"
                    value={formData.location}
                    onChange={(e) => handleInputChange('location', e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="e.g., Accra, Kumasi, Cape Coast"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Venue Name
                  </label>
                  <input
                    type="text"
                    value={formData.venue}
                    onChange={(e) => handleInputChange('venue', e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="e.g., National Theatre, Accra International Conference Centre"
                  />
                </div>
              </div>
            )}

            {currentStep === 3 && (
              <div className="space-y-6">
                <div className="flex justify-between items-center">
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900">Ticket Types</h3>
                    <p className="text-sm text-gray-600">
