'use client';
import React,{useEffect,useRef,useState}from'react';
import {base44}from'@/api/base44Client';
import {mwakwaData,type MwakwaUser}from'@/lib/mwakwaBackend';
type Props={user:MwakwaUser|null};type Row=Record<string,unknown>&{id?:string;title?:string};type ScanResult={success?:boolean;result?:string;message?:string;event?:{title?:string};ticket?:{type?:string;buyer_email?:string}};type BarcodeDetectorCtor=new(options:{formats:string[]})=>{detect(video:HTMLVideoElement):Promise<Array<{rawValue?:string}>>};type ManifestTicket={ticket_id:string;code_hash:string;status:string;ticket_type:string};type Manifest={event:{id:string;title:string};version:string;generated_at:string;tickets:ManifestTicket[]};type Queued={client_checkin_id:string;qr_code:string;client_scanned_at:string;ticket_id:string};
const device=()=>{let d=localStorage.getItem('mwakwa-checkin-device');if(!d){d=crypto.randomUUID();localStorage.setItem('mwakwa-checkin-device',d)}return d};const key=(e:string)=>`mwakwa-manifest:${e}`,qkey=(e:string)=>`mwakwa-checkins:${e}`;const hash=async(v:string)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v.trim().toUpperCase())))).map(b=>b.toString(16).padStart(2,'0')).join('');
export default function TicketScanner({user}:Props){const[events,setEvents]=useState<Row[]>([]),[eventId,setEventId]=useState(''),[code,setCode]=useState(''),[result,setResult]=useState<ScanResult|null>(null),[busy,setBusy]=useState(false),[camera,setCamera]=useState(false),[online,setOnline]=useState(true),[manifest,setManifest]=useState<Manifest|null>(null),[queued,setQueued]=useState<Queued[]>([]);const videoRef=useRef<HTMLVideoElement|null>(null),streamRef=useRef<MediaStream|null>(null),timerRef=useRef<number|undefined>(undefined);
 useEffect(()=>{setOnline(navigator.onLine);const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);if(user)mwakwaData.events.filter({organizer_id:user.id},'-event_date',100,0).then(setEvents).catch(console.error);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off);stopCamera()}},[user]);
 useEffect(()=>{if(!eventId){setManifest(null);setQueued([]);return}try{setManifest(JSON.parse(localStorage.getItem(key(eventId))||'null'));setQueued(JSON.parse(localStorage.getItem(qkey(eventId))||'[]'))}catch{setManifest(null);setQueued([])}},[eventId]);
 const saveQ=(x:Queued[])=>{setQueued(x);localStorage.setItem(qkey(eventId),JSON.stringify(x))};
 const download=async()=>{if(!eventId||!online)return;setBusy(true);try{const r=await base44.functions.invoke('download-checkin-manifest',{event_id:eventId,device_reference:device(),device_label:navigator.userAgent.slice(0,100)});localStorage.setItem(key(eventId),JSON.stringify(r.data));setManifest(r.data);setResult({success:true,message:`Offline list ready: ${r.data.tickets.length} tickets`})}catch(e:unknown){setResult({success:false,message:e instanceof Error?e.message:'Could not prepare offline list'})}finally{setBusy(false)}};
 const sync=async()=>{if(!eventId||!online||!queued.length)return;setBusy(true);try{const r=await base44.functions.invoke('sync-offline-checkins',{event_id:eventId,device_reference:device(),items:queued});const results=r.data.results as Array<{client_checkin_id:string;result:string}>;const done=new Set(results.map(x=>x.client_checkin_id));saveQ(queued.filter(x=>!done.has(x.client_checkin_id)));await download();const dup=results.filter(x=>x.result==='already_used').length;setResult({success:dup===0,message:`Synced ${results.length} offline check-ins${dup?`; ${dup} duplicate admission conflict${dup>1?'s':''} flagged`:''}.`})}catch(e:unknown){setResult({success:false,message:e instanceof Error?e.message:'Sync failed'})}finally{setBusy(false)}};
 const offlineCheck=async(raw:string)=>{if(!eventId||!manifest){setResult({success:false,message:'Select an event and prepare its offline ticket list while connected first.'});return}const h=await hash(raw),t=manifest.tickets.find(x=>x.code_hash===h);if(!t){setResult({success:false,result:'invalid',message:'Ticket is not in this offline event list.'});return}if(t.status!=='confirmed'){setResult({success:false,result:t.status,message:`Ticket is ${t.status}. Do not admit.`});return}if(queued.some(x=>x.ticket_id===t.ticket_id)){setResult({success:false,result:'already_used',message:'This ticket was already scanned on this device.'});return}const x={client_checkin_id:crypto.randomUUID(),qr_code:raw.trim().toUpperCase(),client_scanned_at:new Date().toISOString(),ticket_id:t.ticket_id};saveQ([...queued,x]);setResult({success:true,result:'accepted',message:'OFFLINE ACCESS GRANTED — queued for reconciliation.',event:{title:manifest.event.title},ticket:{type:t.ticket_type}});setCode('')};
 const check=async(raw:string)=>{const value=raw.trim();if(!value||busy)return;if(!online){await offlineCheck(value);return}setBusy(true);try{const r=await base44.functions.invoke('check-in-ticket',{qr_code:value,event_id:eventId||undefined,device_reference:device()});setResult(r.data);if(r.data?.success)setCode('')}catch{if(manifest&&eventId)await offlineCheck(value);else setResult({success:false,message:'Network unavailable and no offline event list is prepared.'})}finally{setBusy(false)}};
 const stopCamera=()=>{if(timerRef.current)clearInterval(timerRef.current);streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=null;setCamera(false)};const startCamera=async()=>{if(!('BarcodeDetector'in window)){setResult({success:false,message:'Live QR scanning is not supported by this browser. Enter the ticket code manually.'});return}try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});streamRef.current=s;if(videoRef.current){videoRef.current.srcObject=s;await videoRef.current.play()}setCamera(true);const D=(window as unknown as{BarcodeDetector:BarcodeDetectorCtor}).BarcodeDetector,d=new D({formats:['qr_code']});timerRef.current=window.setInterval(async()=>{if(!videoRef.current||busy)return;try{const h=await d.detect(videoRef.current);if(h[0]?.rawValue){stopCamera();await check(h[0].rawValue)}}catch{}},500)}catch(e:unknown){setResult({success:false,message:e instanceof Error?e.message:'Camera unavailable'})}};
 const tone=result?.success?'border-green-300 bg-green-50 text-green-900':result?'border-red-300 bg-red-50 text-red-900':'border-gray-200 bg-white';return <div className="space-y-6"><div className="flex flex-wrap justify-between gap-3"><div><h2 className="text-2xl font-bold">Ticket Scanner</h2><p className="text-sm text-gray-600">Online validation with offline-first gate fallback.</p></div><span className={`rounded-full px-3 py-1 text-sm ${online?'bg-green-100 text-green-800':'bg-amber-100 text-amber-900'}`}>{online?'Online':'Offline'}</span></div><div className="grid lg:grid-cols-2 gap-6"><section className="bg-white border rounded-xl p-5 space-y-4"><select className="w-full border rounded-lg px-3 py-3" value={eventId} onChange={e=>setEventId(e.target.value)}><option value="">Select event</option>{events.map(e=><option key={e.id} value={String(e.id||'')}>{String(e.title||'Untitled')}</option>)}</select><div className="grid sm:grid-cols-2 gap-2"><button disabled={!eventId||!online||busy} onClick={download} className="rounded-lg border px-3 py-3 disabled:opacity-40">Prepare offline list</button><button disabled={!eventId||!online||!queued.length||busy} onClick={sync} className="rounded-lg border px-3 py-3 disabled:opacity-40">Sync queued ({queued.length})</button></div>{manifest&&<p className="text-xs text-gray-500">Offline list: {manifest.tickets.length} tickets · prepared {new Date(manifest.generated_at).toLocaleString()}</p>}<div className="flex gap-2"><input className="flex-1 border rounded-lg px-3 py-3" value={code} onChange={e=>setCode(e.target.value)} onKeyDown={e=>e.key==='Enter'&&check(code)} placeholder="Scan or enter ticket code"/><button disabled={busy||!code.trim()} onClick={()=>check(code)} className="rounded-lg bg-blue-600 disabled:bg-gray-300 text-white px-5">Check in</button></div><button onClick={camera?stopCamera:startCamera} className="w-full rounded-lg border px-4 py-3">{camera?'Stop camera':'Open QR camera'}</button><video ref={videoRef} playsInline muted className={`${camera?'block':'hidden'} w-full rounded-xl bg-black aspect-video object-cover`}/></section><section className={`border rounded-xl p-6 ${tone}`}><h3 className="font-semibold text-lg">Gate result</h3>{!result?<p className="mt-3 text-sm">Waiting for a ticket.</p>:<div className="mt-3 space-y-2"><p className="text-2xl font-bold">{result.success?'ACCESS GRANTED':'DO NOT ADMIT'}</p><p>{result.message}</p>{result.event?.title&&<p className="text-sm"><b>Event:</b> {result.event.title}</p>}{result.ticket?.type&&<p className="text-sm"><b>Ticket:</b> {result.ticket.type}</p>}</div>}</section></div><div className="rounded-xl bg-amber-50 border border-amber-200 p-4 text-sm text-amber-900"><b>Offline rule:</b> prepare the event list before doors open. Each device prevents duplicate scans locally. When devices reconnect, Mwakwa reconciles all check-ins; a ticket admitted independently by two offline devices is flagged as a duplicate conflict rather than silently accepted twice.</div></div>}

