"use client";
import React from "react";
import Image from "next/image";

interface PromotionalBannerProps {
  /** Banner image URL */
  imageUrl: string;
  /** Alt text for the banner image */
  altText: string;
  /** Click destination URL */
  href: string;
  /** Whether to open link in new tab (default: true) */
  openInNewTab?: boolean;
  /** Optional overlay text for the banner */
  overlayText?: {
    title?: string;
    subtitle?: string;
    buttonText?: string;
  };
  /** Banner height in pixels (default: 200) */
  height?: number;
  /** Whether banner is currently active/visible (default: true) */
  isActive?: boolean;
  /** Optional click tracking function */
  onBannerClick?: () => void;
  /** Custom CSS classes */
  className?: string;
}

const PromotionBanner: React.FC<PromotionalBannerProps> = ({
  imageUrl,
  altText,
  href,
  openInNewTab = true,
  overlayText,
  height = 200,
  isActive = true,
  onBannerClick,
  className = "",
}) => {
  // Don't render if banner is not active
  if (!isActive) return null;

  const handleClick = () => {
    // Track the click for analytics
    if (onBannerClick) {
      onBannerClick();
    }

    // Optional: Add analytics tracking here
    // analytics.track('promotional_banner_clicked', { href, altText });
  };

  const bannerContent = (
    <div 
      className={`relative w-full overflow-hidden rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 cursor-pointer group ${className}`}
      style={{ height: `${height}px` }}
      onClick={handleClick}
    >
      {/* Banner Image */}
      <Image
        src={imageUrl}
        alt={altText}
        fill
        className="object-cover transition-transform duration-300 group-hover:scale-105"
        sizes="(max-width: 768px) 100vw, (max-width: 1200px) 100vw, 100vw"
        priority={false}
      />

      {/* Optional Overlay Content */}
      {overlayText && (
        <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
          <div className="text-center text-white px-4">
            {overlayText.title && (
              <h3 className="text-2xl md:text-3xl font-bold mb-2">
                {overlayText.title}
              </h3>
            )}
            {overlayText.subtitle && (
              <p className="text-lg md:text-xl mb-4 opacity-90">
                {overlayText.subtitle}
              </p>
            )}
            {overlayText.buttonText && (
              <button className="bg-white text-gray-900 px-6 py-3 rounded-lg font-semibold hover:bg-gray-100 transition-colors">
                {overlayText.buttonText}
              </button>
            )}
          </div>
        </div>
      )}

      {/* Hover effect overlay */}
      <div className="absolute inset-0 bg-blue-600/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />

      {/* "Ad" label for transparency */}
      <div className="absolute top-2 right-2 bg-gray-900/70 text-white text-xs px-2 py-1 rounded">
        Ad
      </div>
    </div>
  );

  // Wrap in link
  if (href) {
    return (
      <a
        href={href}
        target={openInNewTab ? "_blank" : "_self"}
        rel={openInNewTab ? "noopener noreferrer" : undefined}
        className="block"
      >
        {bannerContent}
      </a>
    );
  }

  return bannerContent;
};

export default PromotionBanner;

"use client";
import React, { useEffect, useMemo, useState } from "react";
import PromotionalBanner from "./PromotionBanner";
import { mwakwaData } from "@/lib/mwakwaBackend";

type BannerRow = {
  id: string; title?: string; subtitle?: string; button_text?: string; image_url?: string;
  alt_text?: string; target_url?: string; open_in_new_tab?: boolean; is_active?: boolean;
  starts_at?: string; ends_at?: string; display_order?: number; click_count?: number; impression_count?: number;
};

export default function PromotionBannerSection({ maxBanners = 1, sectionTitle, className = "" }: { maxBanners?: number; sectionTitle?: string; className?: string }) {
  const [rows, setRows] = useState<BannerRow[]>([]);
  useEffect(() => {
    mwakwaData.promotionBanners.list("display_order", 50, 0).then(r => setRows(r as BannerRow[])).catch(() => setRows([]));
  }, []);

  const active = useMemo(() => {
    const now = Date.now();
    return rows.filter(b => b.is_active !== false && (!b.starts_at || new Date(b.starts_at).getTime() <= now) && (!b.ends_at || new Date(b.ends_at).getTime() >= now)).slice(0, maxBanners);
  }, [rows, maxBanners]);

  useEffect(() => {
    active.forEach(b => mwakwaData.promotionBanners.update(b.id, { impression_count: (b.impression_count || 0) + 1 }).catch(() => {}));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active.map(b => b.id).join(",")]);

  if (!active.length) return null;
  return <section className={`py-8 ${className}`}><div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
    {sectionTitle && <h2 className="text-center mb-6 text-2xl md:text-3xl font-bold">{sectionTitle}</h2>}
    <div className={`space-y-6 ${maxBanners > 1 ? "md:space-y-0 md:grid md:grid-cols-2 md:gap-6" : ""}`}>
      {active.map(b => <PromotionalBanner key={b.id} imageUrl={b.image_url || ""} altText={b.alt_text || b.title || "Mwakwa promotion"} href={b.target_url || "/events"} openInNewTab={b.open_in_new_tab} overlayText={{ title: b.title, subtitle: b.subtitle, buttonText: b.button_text }} onBannerClick={() => mwakwaData.promotionBanners.update(b.id, { click_count: (b.click_count || 0) + 1 }).catch(() => {})} />)}
    </div>
  </div></section>;
}

